const KNOWLEDGE_CATALOG = KNOWLEDGE_ROWS.map(([chapter, title, importance, difficulty, definition, explanation, memory, exam, pitfall]) => ({
  id: `${chapter}-${KNOWLEDGE_ROWS.filter(row => row[0] === chapter).findIndex(row => row[1] === title) + 1}`,
  chapter, title, importance, difficulty, definition, explanation, memory, exam, pitfall
}));

function knowledgeByTitle(title) {
  return KNOWLEDGE_CATALOG.find(item => item.title === title);
}
